def balanced(s):
    stack = []
    i = 0
    n = len(s)
    in_string = False
    quote_char = None
    escape = False
    while i < n:
        ch = s[i]
        if not in_string:
            if ch == '"' or ch == "'":
                in_string = True
                quote_char = ch
                escape = False
            elif ch in '([{':
                stack.append(ch)
            elif ch in ')]}':
                if not stack:
                    return False
                top = stack.pop()
                if (top == '(' and ch != ')') or (top == '[' and ch != ']') or (top == '{' and ch != '}'):
                    return False
            # else ignore
        else:  # inside string
            if escape:
                escape = False
            else:
                if ch == '\\':
                    escape = True
                elif ch == quote_char:
                    in_string = False
                    quote_char = None
                # else ordinary char
        i += 1
    if in_string:
        return False
    return not stack

tests = [
    ('([]{})', True),
    ('([)]', False),
    ('f("(")', True),
    ('"abc', False),
    ('', True),
]

all_pass = True
for s, expected in tests:
    res = balanced(s)
    if res != expected:
        print(f"FAIL: {repr(s)} expected {expected} got {res}")
        all_pass = False
if all_pass:
    print("ALL TESTS PASSED")
else:
    print("SOME TESTS FAILED")

